LM.LAB = {"axes":{"columns":[{"id":"past","label":"Past"},{"id":"present","label":"Present"},{"id":"future","label":"Future"}],"rows":[{"id":"indicative","label":"Indicative"},{"id":"subjunctive","label":"Subjunctive"},{"id":"other","label":"Imperative and conditional"}]},"cards":[{"id":"presente","name":"Presente","nameEn":"Present","column":"present","row":"indicative","level":"A1","summary":"What is true now, what you do regularly, and general facts.","formation":[{"label":"Person order","text":"yo, tú, él / ella / usted, nosotros, vosotros (Spain), ellos / ellas / ustedes"},{"label":"-ar verbs","text":"hablo, hablas, habla, hablamos, habláis, hablan"},{"label":"-er verbs","text":"como, comes, come, comemos, coméis, comen"},{"label":"-ir verbs","text":"vivo, vives, vive, vivimos, vivís, viven"},{"label":"Stem changes (not in nosotros, vosotros)","text":"querer: quiero, quieres… queremos · poder: puedo, puedes… podemos · pedir: pido, pides… pedimos"},{"label":"Irregular yo form","text":"hacer: hago · tener: tengo · salir: salgo · poner: pongo · conocer: conozco"}],"uses":[{"label":"True now","text":"Vivo en un apartamento pequeño cerca del centro.","en":"I live in a small apartment near downtown."},{"label":"Habits and routines","text":"Los sábados juego al tenis con mi hermana.","en":"On Saturdays I play tennis with my sister."},{"label":"General facts","text":"El sol sale por el este.","en":"The sun rises in the east."},{"label":"Happening at the moment","text":"¿Qué haces? —Leo una novela.","en":"What are you doing? —I'm reading a novel."},{"label":"Fixed plans and timetables","text":"Mañana trabajo hasta las ocho.","en":"Tomorrow I'm working until eight."}],"signals":["siempre","normalmente","todos los días","los lunes","a veces","nunca","ahora"],"scenes":[{"id":"habit","label":"Habit","description":"The same action again and again: before now, now and after now.","elements":[{"kind":"repeat","from":-0.9,"to":0.9,"count":7,"label":"every Saturday"}]},{"id":"now","label":"Right now","description":"An action that is going on at the moment of speaking.","elements":[{"kind":"range","from":-0.2,"to":0.2,"label":"I'm reading"}]},{"id":"fact","label":"General fact","description":"Something that is always true, with no start and no end.","elements":[{"kind":"range","from":-0.95,"to":0.95,"label":"always true"}]}],"traps":["English says “I'm reading” for an action going on now. Spanish can just use the present: Leo una novela. Estoy leyendo is also very common, but you do not need it every time.","The ending already shows the person, so the subject pronoun is usually left out: Vivo en Lima. Using yo in every sentence sounds unnatural; keep it for emphasis or contrast.","Stem changes do not happen in the nosotros and vosotros forms: queremos, podemos, not *quieremos, *puedemos."],"contrasts":[{"with":"ir-a-infinitivo","rule":"Both can talk about the future. The present with a time word sounds fixed, like a timetable or an arrangement. Ir a + infinitive puts the plan or intention first.","examples":["El tren sale a las nueve.","Mañana voy a llamar a mi madre."]}],"topicIds":["a1-verbs-present-regular","a1-verbs-present-irregular"],"setTags":["present"]},{"id":"preterito-indefinido","name":"Pretérito indefinido","nameEn":"Preterite","column":"past","row":"indicative","level":"A2","summary":"Finished actions at a definite time in the past.","formation":[{"label":"Person order","text":"yo, tú, él / ella / usted, nosotros, vosotros (Spain), ellos / ellas / ustedes"},{"label":"-ar verbs","text":"hablé, hablaste, habló, hablamos, hablasteis, hablaron"},{"label":"-er and -ir verbs","text":"comí, comiste, comió, comimos, comisteis, comieron"},{"label":"Common irregulars","text":"ser / ir: fui, fuiste, fue… · hacer: hice, hiciste, hizo… · tener: tuve… · estar: estuve…"}],"uses":[{"label":"One finished action","text":"Ayer comí con Lucía.","en":"Yesterday I had lunch with Lucía."},{"label":"A chain of actions","text":"Llegué a casa, cené y me acosté.","en":"I got home, had dinner and went to bed."},{"label":"A closed period of time","text":"Viví tres años en Lima.","en":"I lived in Lima for three years."}],"signals":["ayer","anoche","el lunes","la semana pasada","en 2019","hace dos años"],"scenes":[{"id":"point","label":"Finished action","description":"One completed action at a definite moment before now.","elements":[{"kind":"point","at":-0.5}]},{"id":"chain","label":"Chain of actions","description":"Finished actions one after another, each one moving the story on.","elements":[{"kind":"point","at":-0.75,"label":"got home"},{"kind":"point","at":-0.5,"label":"had dinner"},{"kind":"point","at":-0.25,"label":"went to bed"}]},{"id":"period","label":"Closed period","description":"A period with a clear start and end, completely over now.","elements":[{"kind":"range","from":-0.85,"to":-0.35,"label":"three years in Lima"}]}],"traps":["The English simple past covers both one finished event and a habit: “I ate there yesterday” / “As a kid I ate there every Sunday”. Spanish separates them: comí (once, finished) and comía (habit or background).","Present yo and preterite él differ only by the accent: hablo (I speak) / habló (he or she spoke). The preterite yo form is hablé."],"contrasts":[{"with":"preterito-imperfecto","rule":"Indefinido moves the story forward. Imperfecto paints the background.","examples":["Llovía cuando salí de casa.","De niño jugaba al fútbol; un día me rompí la pierna."]}],"topicIds":["a2-verbs-preterite-regular","a2-verbs-preterite-irregular"],"setTags":["preterite"]},{"id":"preterito-imperfecto","name":"Pretérito imperfecto","nameEn":"Imperfect","column":"past","row":"indicative","level":"A2","summary":"Descriptions, background and habits in the past.","formation":[{"label":"Person order","text":"yo, tú, él / ella / usted, nosotros, vosotros (Spain), ellos / ellas / ustedes"},{"label":"-ar verbs","text":"hablaba, hablabas, hablaba, hablábamos, hablabais, hablaban"},{"label":"-er and -ir verbs","text":"comía, comías, comía, comíamos, comíais, comían"},{"label":"The only irregulars","text":"ser: era, eras, era, éramos, erais, eran · ir: iba, ibas, iba, íbamos, ibais, iban · ver: veía, veías, veía…"}],"uses":[{"label":"Habits in the past","text":"De niña vivía en un pueblo e iba a la escuela a pie.","en":"As a girl I lived in a village and walked to school."},{"label":"Descriptions","text":"La casa era vieja y tenía un jardín enorme.","en":"The house was old and had a huge garden."},{"label":"Background to an event","text":"Hacía frío y llovía cuando llegamos.","en":"It was cold and raining when we arrived."},{"label":"Time and how someone felt","text":"Eran las once y yo tenía mucho sueño.","en":"It was eleven o'clock and I was very sleepy."}],"signals":["antes","de niño / de niña","siempre","todos los veranos","normalmente","mientras","cuando era joven"],"scenes":[{"id":"habit","label":"Past habit","description":"Something that happened again and again in the past and does not happen now.","elements":[{"kind":"repeat","from":-0.95,"to":-0.3,"count":5,"label":"every summer"}]},{"id":"background","label":"Background","description":"A situation going on in the past, with no clear start or end, while something else happened.","elements":[{"kind":"range","from":-0.85,"to":-0.2,"label":"it was raining"},{"kind":"point","at":-0.5,"label":"we arrived"}]},{"id":"description","label":"Description","description":"What a person, place or thing was like at that time.","elements":[{"kind":"open-left","to":-0.3,"label":"the house was old"}]}],"traps":["English “used to play” and “was playing” are both often jugaba in Spanish. The imperfecto covers habits and actions in progress.","The imperfecto does not tell you that an action finished. For one finished event at a definite time, use the indefinido: Ayer vi a Pablo. Ayer veía a Pablo sounds unfinished, as if the story goes on.","Watch the accents: hablábamos (only the nosotros form of -ar verbs), but every -er and -ir form has í: comía, vivíamos."],"contrasts":[{"with":"preterito-indefinido","rule":"Imperfecto describes the scene and what used to happen. Indefinido tells what happened next.","examples":["Cuando era pequeño, pasaba los veranos en la playa.","Un verano conocí a mi mejor amigo."]}],"topicIds":["a2-verbs-imperfect","a2-verbs-preterite-vs-imperfect-basics"],"setTags":["imperfect"]},{"id":"ir-a-infinitivo","name":"ir a + infinitivo","nameEn":"going to + infinitive","column":"future","row":"indicative","level":"A1","summary":"Plans, intentions and things that are clearly about to happen.","formation":[{"label":"Pattern","text":"ir (present) + a + infinitivo"},{"label":"All persons","text":"voy a comer, vas a comer, va a comer, vamos a comer, vais a comer (Spain), van a comer"},{"label":"Negative","text":"No voy a salir esta noche."},{"label":"With a pronoun (two places)","text":"Te voy a llamar. / Voy a llamarte."}],"uses":[{"label":"Plans","text":"Este verano vamos a viajar a Perú.","en":"This summer we're going to travel to Peru."},{"label":"Intentions","text":"El próximo año voy a estudiar más.","en":"Next year I'm going to study more."},{"label":"About to happen (you can see it)","text":"¡Cuidado, te vas a caer!","en":"Careful, you're going to fall!"},{"label":"Let's… (vamos a)","text":"Bueno, vamos a empezar.","en":"OK, let's start."}],"signals":["mañana","esta noche","este fin de semana","el próximo año","la semana que viene","pronto"],"scenes":[{"id":"plan","label":"Plan","description":"You decide now; the action comes later.","elements":[{"kind":"point","at":0.6,"label":"the trip"}]},{"id":"soon","label":"About to happen","description":"You can see now that something will happen very soon.","elements":[{"kind":"point","at":0.15,"label":"about to fall"}]}],"traps":["Do not leave out a: Voy a comer, not *Voy comer.","After a comes the infinitive, never a conjugated verb: Vamos a salir, not *Vamos a salimos.","English “I'm going to the movies” has no second verb. In Spanish that is ir a + a place: Voy al cine."],"contrasts":[{"with":"presente","rule":"Ir a + infinitive puts the plan or intention first. The present with a time word sounds fixed, like a timetable or an arrangement.","examples":["Mañana voy a llamar a mi madre.","El tren sale a las nueve."]}],"topicIds":["a1-verbs-ir-a-infinitive"],"setTags":["ir-a"]}],"contrasts":[{"id":"ser-estar","level":"A1","summary":"Two verbs for “to be”: ser says what something is, estar says where it is and how it is right now.","sides":[{"name":"ser","nameEn":"what someone or something is","rules":[{"label":"Identity and jobs","text":"Who or what someone is, including their job.","examples":[{"text":"Soy Marta y soy enfermera.","en":"I'm Marta and I'm a nurse."}]},{"label":"Origin","text":"Where someone or something comes from.","examples":[{"text":"Mis padres son de Bogotá.","en":"My parents are from Bogotá."}]},{"label":"What it is like","text":"Lasting characteristics: personality, looks, size, color.","examples":[{"text":"Tu hermano es muy simpático.","en":"Your brother is very nice."},{"text":"La casa es grande y blanca.","en":"The house is big and white."}]},{"label":"Events","text":"Where or when an event happens: a party, a class, a concert.","examples":[{"text":"La fiesta es en casa de Ana.","en":"The party is at Ana's place."}]},{"label":"Time and dates","text":"The time, the day and the date.","examples":[{"text":"Hoy es lunes y son las cinco.","en":"Today is Monday and it's five o'clock."}]}]},{"name":"estar","nameEn":"where it is and how it is now","rules":[{"label":"Location","text":"Where a person or a thing is, even when it never moves. (Where an event happens takes ser.)","examples":[{"text":"El museo está en el centro.","en":"The museum is downtown."},{"text":"Madrid está en el centro de España.","en":"Madrid is in the center of Spain."}]},{"label":"Feelings and states","text":"How someone feels or what state something is in at the moment.","examples":[{"text":"Estoy cansada porque trabajo mucho.","en":"I'm tired because I work a lot."},{"text":"La ventana está abierta.","en":"The window is open."}]},{"label":"bien and mal","text":"Asking and saying how someone is.","examples":[{"text":"¿Cómo estás? —Estoy bien, gracias.","en":"How are you? —I'm fine, thanks."}]}]}],"tip":"Ask yourself: am I saying what this is, or where it is and how it is right now? What it is → ser. Where it is, or how it is now → estar.","traps":["*Soy cansado → Estoy cansado. Feelings and states take estar.","*Está médico → Es médico. Jobs take ser.","*La farmacia es en esta calle → La farmacia está en esta calle. Location takes estar.","*Soy 20 años → Tengo 20 años. Age takes tener, not ser or estar."],"topicIds":["a1-verbs-ser-vs-estar-basics","a1-verbs-estar-hay","a1-verbs-ser"],"quiz":{"items":[{"id":"lab-ser-estar-q1","type":"multiple-choice","kind":"form","prompt":"Mi madre ___ profesora de inglés.","options":["es","está","tiene","hay"],"correct":0,"explanation":"A job says who someone is, so it takes ser: Mi madre es profesora.","optionNotes":[null,"Estar is not used for jobs.","Tener does not link a person to a job.","Hay means “there is” and does not describe a person."]},{"id":"lab-ser-estar-q2","type":"multiple-choice","kind":"form","prompt":"¿Dónde ___ las llaves? (Where are the keys?)","options":["son","están","es","está"],"correct":1,"explanation":"Location takes estar, and las llaves is plural: ¿Dónde están las llaves?","optionNotes":["Location takes estar, not ser.",null,"Location takes estar, and las llaves is plural.","Estar is right, but las llaves is plural: están."]},{"id":"lab-ser-estar-q3","type":"multiple-choice","kind":"form","prompt":"Ana no va a clase hoy porque ___ enferma.","options":["es","está","tiene","ser"],"correct":1,"explanation":"Being ill is a state at the moment, so it takes estar: Ana está enferma.","optionNotes":["Ser would describe what Ana is like in general, which does not fit an illness today.",null,"Tener needs a noun: tiene fiebre.","Ser is the infinitive; the sentence needs a conjugated verb."]},{"id":"lab-ser-estar-q4","type":"multiple-choice","kind":"form","prompt":"Choose the correct sentence.","options":["Estoy de Valencia, pero ahora soy en Lima.","Soy de Valencia, pero ahora soy en Lima.","Soy de Valencia, pero ahora estoy en Lima.","Estoy de Valencia, pero ahora estoy en Lima."],"correct":2,"explanation":"Origin takes ser (soy de Valencia) and location takes estar (estoy en Lima).","optionNotes":["Both verbs are the wrong way round.","Soy de Valencia is right, but location takes estar: estoy en Lima.",null,"Estoy en Lima is right, but origin takes ser: soy de Valencia."]}]}}],"trees":[{"id":"ser-or-estar","title":"ser or estar?","level":"A1","intro":"Think of the sentence you want to say with “to be”. A few questions lead to the right verb, and sometimes it is neither of the two.","start":"start","nodes":{"start":{"question":"What does “to be” tell us in your sentence?","help":"Pick the closest answer.","options":[{"label":"Where a person or a thing is","result":["ser-estar"],"answer":"estar","why":"Location takes estar, even for places that never move.","example":{"text":"Mi oficina está cerca de la estación.","en":"My office is near the station."}},{"label":"Where an event happens: a party, a class, a concert","result":["ser-estar"],"answer":"ser","why":"Events take ser, also for where they happen.","example":{"text":"La clase es en el aula 3.","en":"The class is in room 3."}},{"label":"Who someone is, their job, or where they are from","result":["ser-estar"],"answer":"ser","why":"Identity, jobs and origin take ser.","example":{"text":"Soy Diego, soy de Quito y soy cocinero.","en":"I'm Diego, I'm from Quito and I'm a cook."}},{"label":"The time, the day or the date","result":["ser-estar"],"answer":"ser","why":"The time and dates take ser.","example":{"text":"Son las tres y media.","en":"It's half past three."}},{"label":"How old someone is","result":["ser-estar"],"answer":"tener","why":"Spanish does not use “to be” for age. Age takes tener.","example":{"text":"Mi hermana tiene quince años.","en":"My sister is fifteen."}},{"label":"What someone or something is like, or how they are","next":"describe"}]},"describe":{"question":"Is it what they are like in general, or how they are at the moment?","help":"Would you say it to describe them to someone who has never met them, or about today?","options":[{"label":"What they are like in general: personality, looks, size, color","result":["ser-estar"],"answer":"ser","why":"Lasting characteristics take ser.","example":{"text":"Mi abuelo es alto y muy tranquilo.","en":"My grandfather is tall and very calm."}},{"label":"How they feel or how they are right now: tired, glad, ill, busy","result":["ser-estar"],"answer":"estar","why":"Feelings and states at the moment take estar.","example":{"text":"Hoy estamos muy ocupados.","en":"We're very busy today."}},{"label":"Just “How are you?” or “I'm fine”","result":["ser-estar"],"answer":"estar","why":"Bien and mal go with estar.","example":{"text":"¿Cómo está tu padre? —Está bien, gracias.","en":"How is your father? —He's fine, thanks."}}]}}}]};
